-- 2026-06-18_07_abaqulusi_annual_repairs_b.sql
-- AbaQulusi gap-fill STEP 5b — Annual matrix repairs (GAP_REGISTER A4,A5). Uses '<field> — <column>' convention (as §6.6/§11.2).
-- A4 §4.4 Sprinklers: split single service set into Diesel/Electric/Sprinkler-valve sub-blocks (Diesel+Electric data was lost).
-- A5 §5.4 Security: add the dropped 'Security Radio' column alongside existing 'Electric fence'. Idempotent.
BEGIN;

-- A4 §4.4 full detail + field_keys rebuild
UPDATE public.inspection_template_items SET field_keys='["As built plan available","If a backup water tank is present, indicate capacity","Number of ICV valves on the premises","What type of sprinkler pump is on premises?","Size and specs of diesel or electrical pump","Size and specs of jockey pump","Diesel, Electrical, Jockey pump","Cost Recovery: Tenant specific / part of ops cost","Current status: (Good, Fair, Poor)","Inspection checklist: Daily/weekly/monthly","General comments","Give a brief description of how the system operates","Diesel day tank capacity — Diesel Pump","Diesel bulk tank capacity — Diesel Pump","Service frequency — Diesel Pump","Last date serviced — Diesel Pump","Next service due — Diesel Pump","Service fee cost — Diesel Pump","Service provider / contractor / installed by — Diesel Pump","Service frequency — Electric Pump","Last date serviced — Electric Pump","Next service due — Electric Pump","Service fee cost — Electric Pump","Service provider / contractor / installed by — Electric Pump","Service frequency — Sprinkler valve","Last date serviced — Sprinkler valve","Next service due — Sprinkler valve","Service fee cost — Sprinkler valve","Service provider / contractor / installed by — Sprinkler valve","Photo (s) reference number:"]'::jsonb WHERE template_id IN (SELECT id FROM public.inspection_templates WHERE name='Annual Building Inspection') AND section_no='4.4';
UPDATE public.inspection_responses ir SET detail='{"As built plan available":"Yes","If a backup water tank is present, indicate capacity":"580KL","Number of ICV valves on the premises":"3","What type of sprinkler pump is on premises?":"Deveron 150KW Diesel Pump","Size and specs of diesel or electrical pump":"Deveson 150KW Pump","Size and specs of jockey pump":"3 KW","Diesel, Electrical, Jockey pump":"Granados Jockey Pumps","Cost Recovery: Tenant specific / part of ops cost":"Tenant and OPS Cost","Current status: (Good, Fair, Poor)":"Good","Inspection checklist: Daily/weekly/monthly":"Weekly","General comments":"None","Give a brief description of how the system operates":"By using heat-sensitive triggers in individual sprinkler heads will automatically release water directly onto a fire, controlling or extinguishing it quickly before it spreads, with only the specific zone activating. Diesel engine to add required pressure.","Diesel day tank capacity — Diesel Pump":"80L","Diesel bulk tank capacity — Diesel Pump":"N/A","Service frequency — Diesel Pump":"Annually","Last date serviced — Diesel Pump":"Serviced 01/2025 under warranty","Next service due — Diesel Pump":"01/2026","Service fee cost — Diesel Pump":"to be confirmed","Service provider / contractor / installed by — Diesel Pump":"Secure fire","Service frequency — Electric Pump":"N/A","Last date serviced — Electric Pump":"N/A","Next service due — Electric Pump":"N/A","Service fee cost — Electric Pump":"N/A","Service provider / contractor / installed by — Electric Pump":"N/A","Service frequency — Sprinkler valve":"Every 3 years","Last date serviced — Sprinkler valve":"08/2023","Next service due — Sprinkler valve":"08/2026","Service fee cost — Sprinkler valve":"1st under warranty cost to be obtained","Service provider / contractor / installed by — Sprinkler valve":"Secure Fire"}'::jsonb
FROM public.inspection_template_items it, public.building_inspections bi
WHERE ir.template_item_id=it.id AND ir.inspection_id=bi.id AND bi.building_id='63345a91-6706-5cf3-b26e-80174c36b2b5' AND it.template_id IN (SELECT id FROM public.inspection_templates WHERE name='Annual Building Inspection') AND it.section_no='4.4';

-- A5 §5.4 add Security Radio column (additive)
UPDATE public.inspection_template_items SET field_keys='["Type of equipment: Provide a list","Brief description of system installed","Quantity of equipment","Current status: (Good, Fair, Poor)","General comment","Repair cost","Service provider / contractor / installed by","Inspection checklist: Daily/weekly/monthly","Type of equipment: Provide a list — Security Radio","Brief description of system installed — Security Radio","Quantity of equipment — Security Radio","Current status: (Good, Fair, Poor) — Security Radio","General comment — Security Radio","Repair cost — Security Radio","Service provider / contractor / installed by — Security Radio","Inspection checklist: Daily/weekly/monthly — Security Radio","Photo (s) reference number:"]'::jsonb WHERE template_id IN (SELECT id FROM public.inspection_templates WHERE name='Annual Building Inspection') AND section_no='5.4';
UPDATE public.inspection_responses ir SET detail = ir.detail || '{"Type of equipment: Provide a list — Security Radio":"Security Radio","Brief description of system installed — Security Radio":"Two way transmission","Quantity of equipment — Security Radio":"11 Radios","Current status: (Good, Fair, Poor) — Security Radio":"Poor (cheap radios)","General comment — Security Radio":"Working condition","Repair cost — Security Radio":"N/A","Service provider / contractor / installed by — Security Radio":"Thompsons","Inspection checklist: Daily/weekly/monthly — Security Radio":"Weekly"}'::jsonb
FROM public.inspection_template_items it, public.building_inspections bi
WHERE ir.template_item_id=it.id AND ir.inspection_id=bi.id AND bi.building_id='63345a91-6706-5cf3-b26e-80174c36b2b5' AND it.template_id IN (SELECT id FROM public.inspection_templates WHERE name='Annual Building Inspection') AND it.section_no='5.4';

COMMIT;
